insert into public.blitz_questions(topic,question,options,correct_index,legal_act,article,source_url,explanation,verified) values
('Муниципальное управление · 33-ФЗ','Муниципалитет проводит опрос жителей и предлагает считать его итог автоматически обязательным для местной администрации. Какова юридическая сила результата?','["Обязательная после опубликования независимо от решения органов","Рекомендательная; опубликование результата не превращает его в обязательное решение","Обязательная при участии более половины жителей","Равная результату местного референдума после утверждения главой"]'::jsonb,1,'Федеральный закон от 20.03.2025 № 33-ФЗ','статья 46','https://www.consultant.ru/document/cons_doc_LAW_501319/9d3746121f118490d463b84d3924d6c398e08596/','По статье 46 Федерального закона № 33-ФЗ применяется указанное полномочие, срок или процедура.',true),
('Муниципальное управление · 33-ФЗ','Администрация получила инициативу опроса жителей. Каков предельный срок принятия представительным органом решения о назначении опроса?','["Три месяца с поступления предусмотренной законом инициативы","Десять дней с регистрации инициативы","Тридцать дней с опубликования проекта","Три месяца после окончания предыдущего опроса"]'::jsonb,0,'Федеральный закон от 20.03.2025 № 33-ФЗ','статья 46','https://www.consultant.ru/document/cons_doc_LAW_501319/9d3746121f118490d463b84d3924d6c398e08596/','По статье 46 Федерального закона № 33-ФЗ применяется указанное полномочие, срок или процедура.',true),
('Муниципальное управление · 33-ФЗ','Жителей известили о муниципальном опросе за семь дней. Какое исправление соответствует статье 46?','["Семидневное уведомление всегда достаточно","Уведомить только за тридцать дней","Срок зависит только от числа предполагаемых участников","Оповестить не менее чем за десять дней до опроса"]'::jsonb,3,'Федеральный закон от 20.03.2025 № 33-ФЗ','статья 46','https://www.consultant.ru/document/cons_doc_LAW_501319/9d3746121f118490d463b84d3924d6c398e08596/','По статье 46 Федерального закона № 33-ФЗ применяется указанное полномочие, срок или процедура.',true),
('Муниципальное управление · 33-ФЗ','Власти субъекта РФ инициировали опрос на территории муниципалитета по вопросам своей компетенции. За счёт какого бюджета финансируется организация опроса?','["За счёт местного бюджета независимо от инициатора","За счёт федерального бюджета во всех случаях","За счёт бюджета соответствующего субъекта Российской Федерации","Исключительно за счёт добровольных платежей жителей"]'::jsonb,2,'Федеральный закон от 20.03.2025 № 33-ФЗ','статья 46','https://www.consultant.ru/document/cons_doc_LAW_501319/9d3746121f118490d463b84d3924d6c398e08596/','По статье 46 Федерального закона № 33-ФЗ применяется указанное полномочие, срок или процедура.',true),
('Муниципальное управление · 33-ФЗ','Жители инициировали опрос о поддержке своего проекта, а администрация требует финансирования из областного бюджета. Какое финансирование следует из статьи 46?','["Бюджет субъекта при любой инициативе на муниципальной территории","Местный бюджет при инициативе жителей муниципалитета","Федеральный бюджет, поскольку вопрос о проекте публичный","Финансирование за счёт инициаторов обязательно"]'::jsonb,1,'Федеральный закон от 20.03.2025 № 33-ФЗ','статья 46','https://www.consultant.ru/document/cons_doc_LAW_501319/9d3746121f118490d463b84d3924d6c398e08596/','По статье 46 Федерального закона № 33-ФЗ применяется указанное полномочие, срок или процедура.',true),
('Муниципальное управление · 33-ФЗ','В проекте решения о муниципальном опросе указаны даты и вопрос, но отсутствует методика опроса. Какой вывод корректен?','["Решение неполно: методика входит в обязательные сведения","Методика всегда определяется только после опроса","Методика нужна только для регионального референдума","Достаточно дат и вопроса при любом способе опроса"]'::jsonb,0,'Федеральный закон от 20.03.2025 № 33-ФЗ','статья 46','https://www.consultant.ru/document/cons_doc_LAW_501319/9d3746121f118490d463b84d3924d6c398e08596/','По статье 46 Федерального закона № 33-ФЗ применяется указанное полномочие, срок или процедура.',true),
('Муниципальное управление · 33-ФЗ','Муниципалитет хочет провести опрос через собственный официальный сайт. Что предусматривает закон?','["Запрещается, опрос всегда проводится только очно","Допускается без какой-либо идентификации при электронном способе","Возможно только с передачей назначения опроса Правительству РФ","Допускается с установленным порядком идентификации участников"]'::jsonb,3,'Федеральный закон от 20.03.2025 № 33-ФЗ','статья 46','https://www.consultant.ru/document/cons_doc_LAW_501319/9d3746121f118490d463b84d3924d6c398e08596/','По статье 46 Федерального закона № 33-ФЗ применяется указанное полномочие, срок или процедура.',true),
('Муниципальное управление · 33-ФЗ','При опросе о поддержке инициативного проекта заявилась группа 18-летних жителей затрагиваемой территории. Какова их правовая возможность участвовать?','["Участие допускается только после достижения возраста 21 года","Участие возможно только при наличии статуса депутата","Они вправе участвовать в специальном опросе по инициативному проекту","Участие возможно только при проживании не менее пяти лет"]'::jsonb,2,'Федеральный закон от 20.03.2025 № 33-ФЗ','статья 46','https://www.consultant.ru/document/cons_doc_LAW_501319/9d3746121f118490d463b84d3924d6c398e08596/','По статье 46 Федерального закона № 33-ФЗ применяется указанное полномочие, срок или процедура.',true),
('Муниципальное управление · 33-ФЗ','Муниципальный представительный орган решил утвердить проект местного бюджета без публичных слушаний. Как оценить процедуру по статье 47?','["Слушания обязательны только по отчёту об исполнении бюджета","Проект местного бюджета подлежит вынесению на публичные слушания","Слушания проводятся исключительно по инициативе главы региона","Слушания заменяются внутренним обсуждением бюджетной комиссии"]'::jsonb,1,'Федеральный закон от 20.03.2025 № 33-ФЗ','статья 47','https://www.consultant.ru/document/cons_doc_LAW_501319/5d1b5174c78b997b5d1ca9641cc99a7106174666/','По статье 47 Федерального закона № 33-ФЗ применяется указанное полномочие, срок или процедура.',true),
('Муниципальное управление · 33-ФЗ','Представительный орган назначает слушания по проекту устава. За какой минимум времени должен быть обеспечен доступ жителей к проекту для обсуждения в рамках статьи 47?','["Не менее десяти дней до проведения публичных слушаний","Не менее пяти дней до проведения публичных слушаний","Не менее тридцати дней после проведения слушаний","Ровно три месяца до голосования по уставу"]'::jsonb,0,'Федеральный закон от 20.03.2025 № 33-ФЗ','статья 47','https://www.consultant.ru/document/cons_doc_LAW_501319/5d1b5174c78b997b5d1ca9641cc99a7106174666/','По статье 47 Федерального закона № 33-ФЗ применяется указанное полномочие, срок или процедура.',true),
('Муниципальное управление · 33-ФЗ','Инициативу публичных слушаний внёс глава местной администрации. Кто назначает эти слушания по статье 47?','["Представительный орган по каждой инициативе без исключений","Глава администрации только по согласованию с региональным парламентом","Организаторы опроса граждан","Глава муниципального образования"]'::jsonb,3,'Федеральный закон от 20.03.2025 № 33-ФЗ','статья 47','https://www.consultant.ru/document/cons_doc_LAW_501319/5d1b5174c78b997b5d1ca9641cc99a7106174666/','По статье 47 Федерального закона № 33-ФЗ применяется указанное полномочие, срок или процедура.',true),
('Муниципальное управление · 33-ФЗ','Инициативу публичных слушаний внесла группа жителей муниципалитета. Кто должен назначить публичные слушания?','["Глава местной администрации единолично","Финансовый орган субъекта Федерации","Представительный орган муниципального образования","Избирательная комиссия муниципального образования"]'::jsonb,2,'Федеральный закон от 20.03.2025 № 33-ФЗ','статья 47','https://www.consultant.ru/document/cons_doc_LAW_501319/5d1b5174c78b997b5d1ca9641cc99a7106174666/','По статье 47 Федерального закона № 33-ФЗ применяется указанное полномочие, срок или процедура.',true),
('Муниципальное управление · 33-ФЗ','Сколько времени отведено уполномоченному местному органу на решение о назначении публичных слушаний после получения инициативы?','["Тридцать дней","Десять дней","Три месяца","Не позднее очередного финансового года"]'::jsonb,1,'Федеральный закон от 20.03.2025 № 33-ФЗ','статья 47','https://www.consultant.ru/document/cons_doc_LAW_501319/5d1b5174c78b997b5d1ca9641cc99a7106174666/','По статье 47 Федерального закона № 33-ФЗ применяется указанное полномочие, срок или процедура.',true),
('Муниципальное управление · 33-ФЗ','Представительный орган получил результаты публичных слушаний по проекту правового акта и решил их не изучать. Какая обязанность нарушается?','["Обязательное рассмотрение результатов при рассмотрении проекта","Обязательное буквальное включение всех замечаний в акт","Обязанность повторного референдума по любому вопросу","Обязанность передать итоги исключительно в Совет Федерации"]'::jsonb,0,'Федеральный закон от 20.03.2025 № 33-ФЗ','статья 47','https://www.consultant.ru/document/cons_doc_LAW_501319/5d1b5174c78b997b5d1ca9641cc99a7106174666/','По статье 47 Федерального закона № 33-ФЗ применяется указанное полномочие, срок или процедура.',true),
('Муниципальное управление · 33-ФЗ','В муниципальном правовом акте предлагается объявить итоги публичных слушаний обязательными для органов власти. Правильно ли определена их юридическая сила?','["Да, при 50-процентной явке слушания равны референдуму","Да, если акт подписан главой администрации","Да, но только если среди участников есть депутаты","Нет, итоги рекомендательны, но должны быть рассмотрены и обнародованы"]'::jsonb,3,'Федеральный закон от 20.03.2025 № 33-ФЗ','статья 47','https://www.consultant.ru/document/cons_doc_LAW_501319/5d1b5174c78b997b5d1ca9641cc99a7106174666/','По статье 47 Федерального закона № 33-ФЗ применяется указанное полномочие, срок или процедура.',true),
('Муниципальное управление · 33-ФЗ','Проводятся общественные обсуждения изменения правил землепользования и застройки. Какой специальный правовой режим применяется?','["Только законодательство о проведении выборов","Только правила о местном референдуме","Законодательство о градостроительной деятельности","Исключительно внутренний регламент регионального парламента"]'::jsonb,2,'Федеральный закон от 20.03.2025 № 33-ФЗ','статья 47','https://www.consultant.ru/document/cons_doc_LAW_501319/5d1b5174c78b997b5d1ca9641cc99a7106174666/','По статье 47 Федерального закона № 33-ФЗ применяется указанное полномочие, срок или процедура.',true),
('Муниципальное управление · 33-ФЗ','Жители решили провести собрание по своему обращению о благоустройстве территории. Кто назначает собрание по инициативе населения в общем порядке?','["Федеральный финансовый орган","Представительный орган муниципального образования по установленному им порядку","Глава субъекта без участия муниципалитета","Территориальная избирательная комиссия"]'::jsonb,1,'Федеральный закон от 20.03.2025 № 33-ФЗ','статья 48','https://www.consultant.ru/document/cons_doc_LAW_501319/70826b358336c60c0dfa29bee1d8f3007c4469b7/','По статье 48 Федерального закона № 33-ФЗ применяется указанное полномочие, срок или процедура.',true),
('Муниципальное управление · 33-ФЗ','Собрание граждан направило обращение по компетенции муниципального органа, но ответа не последовало. Какое требование статьи 48 нарушено?','["Обязательное рассмотрение обращения с направлением письменного ответа","Обязанность обязательно принять предложенный нормативный акт","Обязанность назначить муниципальные выборы","Обязанность провести повторный сход с кворумом 2/3"]'::jsonb,0,'Федеральный закон от 20.03.2025 № 33-ФЗ','статья 48','https://www.consultant.ru/document/cons_doc_LAW_501319/70826b358336c60c0dfa29bee1d8f3007c4469b7/','По статье 48 Федерального закона № 33-ФЗ применяется указанное полномочие, срок или процедура.',true),
('Муниципальное управление · 33-ФЗ','Кто в предусмотренных законом случаях может проводить собрание по вопросу выдвижения старосты сельского населённого пункта?','["Только региональная избирательная комиссия","Только депутаты Государственной Думы","Исключительно руководители государственных учреждений","Граждане на собрании соответствующего сельского населённого пункта"]'::jsonb,3,'Федеральный закон от 20.03.2025 № 33-ФЗ','статья 48','https://www.consultant.ru/document/cons_doc_LAW_501319/70826b358336c60c0dfa29bee1d8f3007c4469b7/','По статье 48 Федерального закона № 33-ФЗ применяется указанное полномочие, срок или процедура.',true),
('Муниципальное управление · 33-ФЗ','Какое правило действует для решения собрания жителей о выдвижении кандидатуры сельского старосты?','["Две трети голосов всех жителей муниципального округа","Три четверти присутствующих депутатов областного парламента","Большинство голосов участников собрания","Единогласие всех зарегистрированных избирателей области"]'::jsonb,2,'Федеральный закон от 20.03.2025 № 33-ФЗ','статья 48','https://www.consultant.ru/document/cons_doc_LAW_501319/70826b358336c60c0dfa29bee1d8f3007c4469b7/','По статье 48 Федерального закона № 33-ФЗ применяется указанное полномочие, срок или процедура.',true),
('Муниципальное управление · 33-ФЗ','Шесть совершеннолетних жителей подготовили инициативный проект, а акт представительного органа не уменьшал минимальный состав группы. Какое требование не соблюдено?','["Минимальный размер группы — восемь граждан","Минимальный размер инициативной группы — десять граждан","Нужна группа не менее пятнадцати жителей","Минимум равен пяти процентам избирателей муниципалитета"]'::jsonb,1,'Федеральный закон от 20.03.2025 № 33-ФЗ','статья 49','https://www.consultant.ru/document/cons_doc_LAW_501319/07d01c5cc986e77d47e5b098e7a80cb185dde940/','По статье 49 Федерального закона № 33-ФЗ применяется указанное полномочие, срок или процедура.',true),
('Муниципальное управление · 33-ФЗ','Муниципальный правовой акт разрешил инициативу группы из восьми совершеннолетних жителей. Может ли это соответствовать статье 49?','["Да, представительный орган вправе уменьшить установленный законом минимум","Нет, федеральный минимум в десять граждан не может изменяться","Да, если инициативу дополнительно утвердит губернатор","Нет, только один староста вправе инициировать проект"]'::jsonb,0,'Федеральный закон от 20.03.2025 № 33-ФЗ','статья 49','https://www.consultant.ru/document/cons_doc_LAW_501319/07d01c5cc986e77d47e5b098e7a80cb185dde940/','По статье 49 Федерального закона № 33-ФЗ применяется указанное полномочие, срок или процедура.',true),
('Муниципальное управление · 33-ФЗ','Местная администрация приняла инициативный проект, не обсуждавшийся на сходе или собрании граждан. Какое требование нарушено?','["Обязательное голосование за него в Государственной Думе","Необходимость передать инициативу сначала в Совет Федерации","Условие о прохождении отдельного федерального референдума","Предварительное рассмотрение и поддержка проекта сходом или собранием"]'::jsonb,3,'Федеральный закон от 20.03.2025 № 33-ФЗ','статья 49','https://www.consultant.ru/document/cons_doc_LAW_501319/07d01c5cc986e77d47e5b098e7a80cb185dde940/','По статье 49 Федерального закона № 33-ФЗ применяется указанное полномочие, срок или процедура.',true),
('Муниципальное управление · 33-ФЗ','Какие сведения обязательны в инициативном проекте, для которого планируются средства местного бюджета?','["Только список сторонников проекта и лозунг инициативы","Лишь сведения о частном софинансировании без сметы","Предварительный расчёт расходов и объём необходимых средств местного бюджета","Только итоговая сумма после выполнения работ"]'::jsonb,2,'Федеральный закон от 20.03.2025 № 33-ФЗ','статья 49','https://www.consultant.ru/document/cons_doc_LAW_501319/07d01c5cc986e77d47e5b098e7a80cb185dde940/','По статье 49 Федерального закона № 33-ФЗ применяется указанное полномочие, срок или процедура.',true),
('Муниципальное управление · 33-ФЗ','Через какой срок после поступления инициативного проекта местная администрация должна его обязательно рассмотреть?','["В течение десяти рабочих дней со дня опубликования","В течение тридцати дней со дня внесения","В течение трёх месяцев с даты проведения схода","В течение одного года со дня подачи заявления"]'::jsonb,1,'Федеральный закон от 20.03.2025 № 33-ФЗ','статья 49','https://www.consultant.ru/document/cons_doc_LAW_501319/07d01c5cc986e77d47e5b098e7a80cb185dde940/','По статье 49 Федерального закона № 33-ФЗ применяется указанное полномочие, срок или процедура.',true),
('Муниципальное управление · 33-ФЗ','Какой срок предусмотрен для обнародования сведений о внесённом инициативном проекте на официальном сайте муниципалитета?','["В течение трёх рабочих дней со дня внесения","В течение пяти календарных дней после принятия итогового решения","В течение одного месяца после проведения конкурса","В течение десяти рабочих дней после окончания сбора замечаний"]'::jsonb,0,'Федеральный закон от 20.03.2025 № 33-ФЗ','статья 49','https://www.consultant.ru/document/cons_doc_LAW_501319/07d01c5cc986e77d47e5b098e7a80cb185dde940/','По статье 49 Федерального закона № 33-ФЗ применяется указанное полномочие, срок или процедура.',true),
('Муниципальное управление · 33-ФЗ','Муниципалитет открыл приём замечаний к инициативному проекту всего на три рабочих дня. Какое правило нарушено?','["Срок должен составлять ровно тридцать рабочих дней","Срок не ограничен федеральным законом ни при каких обстоятельствах","Замечания принимаются только в течение одного рабочего дня","Срок для замечаний не может быть менее пяти рабочих дней"]'::jsonb,3,'Федеральный закон от 20.03.2025 № 33-ФЗ','статья 49','https://www.consultant.ru/document/cons_doc_LAW_501319/07d01c5cc986e77d47e5b098e7a80cb185dde940/','По статье 49 Федерального закона № 33-ФЗ применяется указанное полномочие, срок или процедура.',true),
('Муниципальное управление · 33-ФЗ','Администрация обнаружила более эффективный способ решить заявленную жителями проблему. Что она должна предпринять при отказе по этому основанию?','["Безусловно запретить повторное внесение любой инициативы","Автоматически передать проект в федеральное министерство","Предложить инициаторам совместно доработать проект","Снять с обсуждения проект без разъяснения причин"]'::jsonb,2,'Федеральный закон от 20.03.2025 № 33-ФЗ','статья 49','https://www.consultant.ru/document/cons_doc_LAW_501319/07d01c5cc986e77d47e5b098e7a80cb185dde940/','По статье 49 Федерального закона № 33-ФЗ применяется указанное полномочие, срок или процедура.',true),
('Муниципальное управление · 33-ФЗ','ТОС объявило себя учреждённым после первого собрания, хотя устав не зарегистрирован муниципальным органом. Когда ТОС действительно считается учреждённым?','["С момента подачи заявления в региональный парламент","С момента регистрации устава уполномоченным органом местного самоуправления","С момента первого обращения участников к главе субъекта","С момента утверждения сметы инициативного проекта"]'::jsonb,1,'Федеральный закон от 20.03.2025 № 33-ФЗ','статья 50','https://www.consultant.ru/document/cons_doc_LAW_501319/50787bcb81a98ab5f7a399d8f6f24d887ce06fb1/','По статье 50 Федерального закона № 33-ФЗ применяется указанное полномочие, срок или процедура.',true),
('Муниципальное управление · 33-ФЗ','В территории ТОС проживают 900 совершеннолетних жителей. Сколько участников требуется для правомочности собрания по вопросам ТОС?','["Не менее 300 жителей","Не менее 225 жителей","Не менее 450 жителей","Не менее 600 жителей"]'::jsonb,0,'Федеральный закон от 20.03.2025 № 33-ФЗ','статья 50','https://www.consultant.ru/document/cons_doc_LAW_501319/50787bcb81a98ab5f7a399d8f6f24d887ce06fb1/','По статье 50 Федерального закона № 33-ФЗ применяется указанное полномочие, срок или процедура.',true),
('Муниципальное управление · 33-ФЗ','На конференцию ТОС избраны 90 делегатов. Сколько из них должно участвовать для правомочности конференции при выполнении и других условий?','["Не менее 30 делегатов","Не менее 45 делегатов","Не менее 75 делегатов","Не менее 60 делегатов"]'::jsonb,3,'Федеральный закон от 20.03.2025 № 33-ФЗ','статья 50','https://www.consultant.ru/document/cons_doc_LAW_501319/50787bcb81a98ab5f7a399d8f6f24d887ce06fb1/','По статье 50 Федерального закона № 33-ФЗ применяется указанное полномочие, срок или процедура.',true),
('Муниципальное управление · 33-ФЗ','Жители планируют включить один жилой дом одновременно в два самостоятельных ТОС. Как это соотносится с законом?','["Можно, если советы ТОС заключат соглашение","Можно после одобрения регионального финансового органа","Нельзя: одна территория проживания может входить только в одно ТОС","Можно, если оба ТОС зарегистрированы как НКО"]'::jsonb,2,'Федеральный закон от 20.03.2025 № 33-ФЗ','статья 50','https://www.consultant.ru/document/cons_doc_LAW_501319/50787bcb81a98ab5f7a399d8f6f24d887ce06fb1/','По статье 50 Федерального закона № 33-ФЗ применяется указанное полномочие, срок или процедура.',true),
('Муниципальное управление · 33-ФЗ','Орган ТОС предлагает самостоятельно изменить устав без собрания или конференции жителей. Какой орган обладает исключительной компетенцией?','["Глава местной администрации во всех случаях","Собрание или конференция граждан, осуществляющих ТОС","Контрольно-счётный орган муниципалитета","Региональная избирательная комиссия"]'::jsonb,1,'Федеральный закон от 20.03.2025 № 33-ФЗ','статья 50','https://www.consultant.ru/document/cons_doc_LAW_501319/50787bcb81a98ab5f7a399d8f6f24d887ce06fb1/','По статье 50 Федерального закона № 33-ФЗ применяется указанное полномочие, срок или процедура.',true),
('Муниципальное управление · 33-ФЗ','Постановление главы муниципалитета противоречит уставу муниципального образования. Какой акт имеет большую юридическую силу внутри муниципальной системы?','["Устав муниципального образования","Позднее постановление главы независимо от его содержания","Должностная инструкция сотрудника администрации","План работы представительного органа"]'::jsonb,0,'Федеральный закон от 20.03.2025 № 33-ФЗ','статья 52','https://www.consultant.ru/document/cons_doc_LAW_501319/08c1bc0f3ac3e7fe6b71bf353835ebb5fb2124c0/','По статье 52 Федерального закона № 33-ФЗ применяется указанное полномочие, срок или процедура.',true),
('Муниципальное управление · 33-ФЗ','Решение местного референдума оформлено правовым актом, а представительный орган принимает противоречащий ему акт. Какое решение соответствует статье 52?','["Поздний акт представительного органа всегда отменяет решение референдума","Оба акта равнозначны и действуют параллельно независимо от противоречия","Референдум имеет силу лишь после подтверждения региональным парламентом","Акт представительного органа не должен противоречить результату референдума"]'::jsonb,3,'Федеральный закон от 20.03.2025 № 33-ФЗ','статья 52','https://www.consultant.ru/document/cons_doc_LAW_501319/08c1bc0f3ac3e7fe6b71bf353835ebb5fb2124c0/','По статье 52 Федерального закона № 33-ФЗ применяется указанное полномочие, срок или процедура.',true),
('Муниципальное управление · 33-ФЗ','Муниципалитет проводит оценку регулирующего воздействия проекта об установлении местного налога как обязательную по статье 52. Какое уточнение требуется?','["Оценка обязательна без исключений даже при отсутствии предпринимательских требований","Оценку проводит исключительно Банк России","Проекты актов об установлении местных налогов исключены из этой процедуры","Налоговый акт не является муниципальным правовым актом"]'::jsonb,2,'Федеральный закон от 20.03.2025 № 33-ФЗ','статья 52','https://www.consultant.ru/document/cons_doc_LAW_501319/08c1bc0f3ac3e7fe6b71bf353835ebb5fb2124c0/','По статье 52 Федерального закона № 33-ФЗ применяется указанное полномочие, срок или процедура.',true),
('Муниципальное управление · 33-ФЗ','Представительный орган хочет обсудить принятие нового устава через двадцать дней после опубликования проекта. Какой минимальный срок установлен статьёй 56?','["Проект можно публиковать за четырнадцать дней","Проект публикуется не позднее чем за тридцать дней до рассмотрения","Достаточно опубликования после принятия устава","Проект должен быть размещён ровно за три месяца до заседания"]'::jsonb,1,'Федеральный закон от 20.03.2025 № 33-ФЗ','статья 56','https://www.consultant.ru/document/cons_doc_LAW_501319/396797a41c03bbdc1eee65d00a2b5481675a9e12/','По статье 56 Федерального закона № 33-ФЗ применяется указанное полномочие, срок или процедура.',true),
('Муниципальное управление · 33-ФЗ','В представительном органе установлено 30 депутатских мандатов. Сколько голосов «за» необходимо для принятия устава муниципального образования?','["Не менее двадцати голосов","Не менее шестнадцати голосов","Не менее двадцати двух голосов","Не менее двадцати трёх голосов"]'::jsonb,0,'Федеральный закон от 20.03.2025 № 33-ФЗ','статья 56','https://www.consultant.ru/document/cons_doc_LAW_501319/396797a41c03bbdc1eee65d00a2b5481675a9e12/','По статье 56 Федерального закона № 33-ФЗ применяется указанное полномочие, срок или процедура.',true),
('Муниципальное управление · 33-ФЗ','Представительный орган большинством от присутствующих принял устав, но две трети от установленной численности депутатов не набраны. Какова оценка?','["Устав принят, так как достаточно любого большинства присутствующих","Устав принят автоматически после публичных слушаний","Устав считается утверждённым решением главы администрации","Требуемое квалифицированное большинство не достигнуто"]'::jsonb,3,'Федеральный закон от 20.03.2025 № 33-ФЗ','статья 56','https://www.consultant.ru/document/cons_doc_LAW_501319/396797a41c03bbdc1eee65d00a2b5481675a9e12/','По статье 56 Федерального закона № 33-ФЗ применяется указанное полномочие, срок или процедура.',true),
('Муниципальное управление · 33-ФЗ','Финансовый орган хочет включить смету отдельного населённого пункта, не являющегося муниципальным образованием, в состав местного бюджета. Возможно ли это?','["Нет, любой населённый пункт обязан иметь отдельный самостоятельный бюджет","Да, но только при согласии Министерства обороны","Да, такие сметы допускаются как составная часть муниципального бюджета","Нет, допускаются лишь сметы территориальных органов федеральных ведомств"]'::jsonb,2,'Федеральный закон от 20.03.2025 № 33-ФЗ','статья 65','https://www.consultant.ru/document/cons_doc_LAW_501319/9d634167d21d8a5378b79cf8089b4b6078566750/','По статье 65 Федерального закона № 33-ФЗ применяется указанное полномочие, срок или процедура.',true),
('Муниципальное управление · 33-ФЗ','Администрация отказалась публиковать сведения о ходе исполнения местного бюджета за квартал. Какое правило действует?','["Публикуется только годовой отчёт, квартальные сведения всегда закрыты","Ежеквартальные сведения о ходе исполнения бюджета подлежат официальному опубликованию","Достаточно устного отчёта на заседании без официального опубликования","Правило применяется только к бюджету субъекта РФ"]'::jsonb,1,'Федеральный закон от 20.03.2025 № 33-ФЗ','статья 65','https://www.consultant.ru/document/cons_doc_LAW_501319/9d634167d21d8a5378b79cf8089b4b6078566750/','По статье 65 Федерального закона № 33-ФЗ применяется указанное полномочие, срок или процедура.',true),
('Муниципальное управление · 33-ФЗ','В отношении кандидата на должность руководителя финансового органа муниципального округа не проводилась предусмотренная законом проверка с участием финансового органа субъекта РФ. Как оценить назначение?','["Нужно соблюдать установленную законом проверку квалификационных требований с участием регионального финансового органа","Достаточно исключительно личного решения главы муниципалитета","Проверка заменяется любым устным собеседованием с депутатом","Закон требует проверки только для федеральных министров"]'::jsonb,0,'Федеральный закон от 20.03.2025 № 33-ФЗ','статья 65','https://www.consultant.ru/document/cons_doc_LAW_501319/9d634167d21d8a5378b79cf8089b4b6078566750/','По статье 65 Федерального закона № 33-ФЗ применяется указанное полномочие, срок или процедура.',true),
('Муниципальное управление · 33-ФЗ','Муниципалитет исполняет переданные ему законом субъекта государственные полномочия. Каков основной предусмотренный статьёй 71 источник финансирования этих обязательств?','["Только добровольные пожертвования жителей","Только собственные неналоговые доходы муниципалитета","Субсидии на любое благоустройство без связи с переданными полномочиями","Субвенции из бюджета субъекта Российской Федерации"]'::jsonb,3,'Федеральный закон от 20.03.2025 № 33-ФЗ','статья 71','https://www.consultant.ru/document/cons_doc_LAW_501319/dd0cc50f64bf03b4782e314160b5110439809cab/','По статье 71 Федерального закона № 33-ФЗ применяется указанное полномочие, срок или процедура.',true),
('Муниципальное управление · 33-ФЗ','Органы МСУ выполняют переданные полномочия Российской Федерации. Какая схема субвенций соответствует статье 71?','["Средства муниципальных бюджетов безвозвратно передаются федеральному бюджету","Средства перечисляются исключительно из муниципального резервного фонда","Средства федерального бюджета распределяются через бюджет субъекта местным бюджетам","Субвенции заменяются любыми кредитами коммерческих банков"]'::jsonb,2,'Федеральный закон от 20.03.2025 № 33-ФЗ','статья 71','https://www.consultant.ru/document/cons_doc_LAW_501319/dd0cc50f64bf03b4782e314160b5110439809cab/','По статье 71 Федерального закона № 33-ФЗ применяется указанное полномочие, срок или процедура.',true),
('Муниципальное управление · 33-ФЗ','Регион планирует совместно финансировать создание муниципального объекта по полномочиям местного значения. Какой тип трансферта прямо предусмотрен?','["Субвенция местному бюджету на федеральное полномочие, не переданное законом","Субсидия местному бюджету на софинансирование расходного обязательства","Только возвратный бюджетный кредит, независимо от цели","Исключительно муниципальное заимствование без трансфертов"]'::jsonb,1,'Федеральный закон от 20.03.2025 № 33-ФЗ','статья 72','https://www.consultant.ru/document/cons_doc_LAW_501319/8b1fa2bf9cbcc1b3b5d391f56f485484f9dc65b3/','По статье 72 Федерального закона № 33-ФЗ применяется указанное полномочие, срок или процедура.',true)
